28	void moveFileBetweenDisks(
29	    DiskPtr disk_from,
30	    const std::string & path_from,
31	    DiskPtr disk_to,
32	    const std::string & path_to,
33	    std::function<void()> before_file_remove_op,
34	    LoggerPtr logger,
35	    const KeeperContextPtr & keeper_context)
36	{
37	    LOG_TRACE(logger, "Moving {} to {} from disk {} to disk {}", path_from, path_to, disk_from->getName(), disk_to->getName());
38	    /// we use empty file with prefix tmp_ to detect incomplete copies
39	    /// if a copy is complete we don't care from which disk we use the same file
40	    /// so it's okay if a failure happens after removing of tmp file but before we remove
41	    /// the file from the source disk
42	    auto from_path = fs::path(path_from);
43	    auto tmp_file_name = from_path.parent_path() / (std::string{tmp_keeper_file_prefix} + from_path.filename().string());
44	
45	    const auto & coordination_settings = keeper_context->getFixedCoordinationSettings();
46	    auto max_retries_on_init = coordination_settings[CoordinationSetting::disk_move_retries_during_init].value;
47	    auto retries_sleep = std::chrono::milliseconds(coordination_settings[CoordinationSetting::disk_move_retries_wait_ms]);
48	    auto run_with_retries = [&](const auto & op, std::string_view operation_description)
49	    {
50	        size_t retry_num = 0;
51	        do
52	        {
53	            try
54	            {
55	                op();
56	                return true;
57	            }
58	            catch (...)
59	            {
60	                tryLogCurrentException(
61	                    logger,
62	                    fmt::format(
63	                        "While moving file {} to disk {} and running '{}'", path_from, disk_to->getName(), operation_description));
64	                std::this_thread::sleep_for(retries_sleep);
65	            }
66	
67	            ++retry_num;
68	            if (keeper_context->getServerState() == KeeperContext::Phase::INIT && retry_num == max_retries_on_init)
69	            {
70	                LOG_ERROR(logger, "Operation '{}' failed too many times", operation_description);
71	                break;
72	            }
73	        } while (!keeper_context->isShutdownCalled());
74	
75	        LOG_ERROR(
76	            logger,
77	            "Failed to run '{}' while moving file {} to disk {}",
78	            operation_description,
79	            path_from,
80	            disk_to->getName());
81	        return false;
82	    };
83	
84	    if (!run_with_retries(
85	            [&]
86	            {
87	                auto buf = disk_to->writeFile(tmp_file_name);
88	                buf->finalize();
89	            },
90	            "creating temporary file"))
91	        return;
92	
93	    if (!run_with_retries([&] { disk_from->copyFile(from_path, *disk_to, path_to, {}); }, "copying file"))
94	        return;
95	
96	    if (!run_with_retries([&] { disk_to->removeFileIfExists(tmp_file_name); }, "removing temporary file"))
97	        return;
98	
99	    if (before_file_remove_op)
100	        before_file_remove_op();
101	
102	    if (!run_with_retries([&] { disk_from->removeFileIfExists(path_from); }, "removing file from source disk"))
103	        return;
104	}
