325	                throw Exception(ErrorCodes::LOGICAL_ERROR, "Chosen multipart upload for an empty file. This must not happen");
326	
327	            UInt64 max_part_number = request_settings[S3RequestSetting::max_part_number];
328	            UInt64 min_upload_part_size = request_settings[S3RequestSetting::min_upload_part_size];
329	            UInt64 max_upload_part_size = request_settings[S3RequestSetting::max_upload_part_size];
330	
331	            if (!max_part_number)
332	                throw Exception(ErrorCodes::INVALID_CONFIG_PARAMETER, "max_part_number must not be 0");
333	            if (!min_upload_part_size)
334	                throw Exception(ErrorCodes::INVALID_CONFIG_PARAMETER, "min_upload_part_size must not be 0");
335	            if (max_upload_part_size < min_upload_part_size)
336	                throw Exception(ErrorCodes::INVALID_CONFIG_PARAMETER, "max_upload_part_size must not be less than min_upload_part_size");
337	
338	            size_t part_size = min_upload_part_size;
339	            num_parts = (total_size + part_size - 1) / part_size;
340	
341	            if (num_parts > max_part_number)
342	            {
343	                part_size = (total_size + max_part_number - 1) / max_part_number;
344	                num_parts = (total_size + part_size - 1) / part_size;
345	            }
346	
347	            if (part_size > max_upload_part_size)
348	            {
349	                part_size = max_upload_part_size;
350	                num_parts = (total_size + part_size - 1) / part_size;
351	            }
352	
353	            String error;
354	            if (num_parts < 1)
355	                error = "Number of parts is zero";
356	            else if (num_parts > max_part_number)
357	                error = fmt::format("Number of parts exceeds {}/{}", num_parts, max_part_number);
358	            else if (part_size < min_upload_part_size)
359	                error = fmt::format("Size of a part is less than {}/{}", part_size, min_upload_part_size);
360	            else if (part_size > max_upload_part_size)
361	                error = fmt::format("Size of a part exceeds {}/{}", part_size, max_upload_part_size);
362	
363	            if (!error.empty())
364	            {
365	                throw Exception(
366	                    ErrorCodes::INVALID_CONFIG_PARAMETER,
367	                    "{} while writing {} bytes to S3. Check max_part_number = {}, "
368	                    "min_upload_part_size = {}, max_upload_part_size = {}",
369	                    error, total_size, max_part_number, min_upload_part_size, max_upload_part_size);
370	            }
371	
372	            /// We've calculated the size of a normal part (the final part can be smaller).
373	            normal_part_size = part_size;
